#!/usr/bin/env bash
#
# Opens the sourcegraph/sourcegraph pull request that pins a newly released src-cli version:
#
#   internal/src-cli/consts.go  MinimumVersion, served by /.api/src-cli/version on every instance
#   dev/tool_deps.bzl           SRC_CLI_VERSION and the sha256 of the two release tarballs
#   MODULE.bazel.lock           regenerated by `bazel mod tidy`
#
# Run by .github/workflows/goreleaser.yml after a new latest release. To run locally:
#
#   VERSION=8.0.0 SOURCEGRAPH_DIR=~/git/common-repos/sourcegraph/worktrees/main OPEN_PR=0 dev/open-sourcegraph-bump-pr.sh
#
# Environment:
#   VERSION          src-cli release tag, already published on GitHub            (required)
#   SOURCEGRAPH_DIR  checkout of sourcegraph/sourcegraph to edit                  (required)
#   OPEN_PR          0 edits the checkout and stops, 1 also commits, pushes, and opens the PR (default 1)
#   REVIEWER_TEAM    GitHub team requested as reviewer on the PR                  (default platform)
#   GH_TOKEN         token with push access to sourcegraph/sourcegraph, used by git and gh when OPEN_PR=1

set -euo pipefail

: "${VERSION:?set VERSION to the src-cli release, for example 8.0.0}"
: "${SOURCEGRAPH_DIR:?set SOURCEGRAPH_DIR to a sourcegraph/sourcegraph checkout}"
OPEN_PR="${OPEN_PR:-1}"
REVIEWER_TEAM="${REVIEWER_TEAM:-platform}"
BRANCH="src-cli-bump/${VERSION}"
RELEASE_ASSETS="https://github.com/sourcegraph/src-cli/releases/download/${VERSION}"

echo "--- Reading tarball checksums from the ${VERSION} release"
checksums=$(curl --silent --show-error --fail --location "${RELEASE_ASSETS}/src-cli_${VERSION}_checksums.txt")
checksum_for() {
  awk -v file="src-cli_${VERSION}_$1.tar.gz" '$2 == file { print $1 }' <<<"${checksums}"
}
linux_amd64_sha256=$(checksum_for linux_amd64)
darwin_arm64_sha256=$(checksum_for darwin_arm64)
if [[ -z ${linux_amd64_sha256} || -z ${darwin_arm64_sha256} ]]; then
  echo "src-cli_${VERSION}_checksums.txt does not list both linux_amd64 and darwin_arm64 tarballs:" >&2
  echo "${checksums}" >&2
  exit 1
fi
echo "linux_amd64:  ${linux_amd64_sha256}"
echo "darwin_arm64: ${darwin_arm64_sha256}"

cd "${SOURCEGRAPH_DIR}"

echo "--- Updating internal/src-cli/consts.go and dev/tool_deps.bzl"
sed -i.bak -E "s/^const MinimumVersion = \"[^\"]+\"/const MinimumVersion = \"${VERSION}\"/" internal/src-cli/consts.go
rm internal/src-cli/consts.go.bak
# The sha256 to replace is the first one after each src-cli http_archive name.
awk -v version="${VERSION}" -v linux="${linux_amd64_sha256}" -v darwin="${darwin_arm64_sha256}" '
  /^SRC_CLI_VERSION = "/          { sub(/"[^"]*"/, "\"" version "\"") }
  /name = "src-cli-linux-amd64"/  { pending = linux }
  /name = "src-cli-darwin-arm64"/ { pending = darwin }
  pending != "" && /sha256 = "/   { sub(/sha256 = "[^"]*"/, "sha256 = \"" pending "\""); pending = "" }
  { print }
' dev/tool_deps.bzl >dev/tool_deps.bzl.new && mv dev/tool_deps.bzl.new dev/tool_deps.bzl

echo "--- Regenerating MODULE.bazel.lock"
bazel mod tidy

echo "--- Verifying the pinned tarballs download with the new checksums"
bazel fetch @src-cli-linux-amd64//:src-cli-linux-amd64 @src-cli-darwin-arm64//:src-cli-darwin-arm64

git --no-pager diff --stat
if [[ ${OPEN_PR} != 1 ]]; then
  echo "OPEN_PR=${OPEN_PR}: leaving the changes uncommitted in ${SOURCEGRAPH_DIR}"
  exit 0
fi

echo "--- Committing and pushing ${BRANCH}"
git checkout -b "${BRANCH}"
git add internal/src-cli/consts.go dev/tool_deps.bzl MODULE.bazel.lock
git commit -m "chore/src-cli: update src-cli to ${VERSION}"
git push --set-upstream origin "${BRANCH}"

echo "--- Opening the pull request"
pull_request_url=$(gh pr create \
  --title "chore/src-cli: update src-cli to ${VERSION}" \
  --label no-changelog \
  --body "src-cli ${VERSION} is published on GitHub, Homebrew, and npm, but \`/.api/src-cli/version\` on every Sourcegraph instance keeps recommending the \`MinimumVersion\` pinned here. This raises the pin so instances serve the new release.

Opened automatically by the src-cli [Build and Release](https://github.com/sourcegraph/src-cli/actions/workflows/goreleaser.yml) workflow for https://github.com/sourcegraph/src-cli/releases/tag/${VERSION}.

- Raise \`MinimumVersion\` in \`internal/src-cli/consts.go\`
- Update \`SRC_CLI_VERSION\` and the tarball checksums in \`dev/tool_deps.bzl\`
- Regenerate \`MODULE.bazel.lock\` with \`bazel mod tidy\`

## Test Plan

CI. The workflow verified the checksums with:

\`\`\`shell
bazel fetch @src-cli-linux-amd64//:src-cli-linux-amd64 @src-cli-darwin-arm64//:src-cli-darwin-arm64
\`\`\`")
echo "${pull_request_url}"
gh api --method POST "repos/sourcegraph/sourcegraph/pulls/${pull_request_url##*/}/requested_reviewers" \
  -f "team_reviewers[]=${REVIEWER_TEAM}" >/dev/null
echo "Requested review from @sourcegraph/${REVIEWER_TEAM}"
